from pathlib import Path
root=Path(__file__).resolve().parents[1]
def edit(rel,changes):
 p=root/rel;s=p.read_text(encoding='utf-8')
 for a,b in changes:
  if a not in s:
   print('MISSING:',rel,repr(a[:100]));continue
  s=s.replace(a,b)
 p.write_text(s,encoding='utf-8')
